
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_r2scan01_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_r2scan01", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.656281228697622e-02, -2.651920038850088e-02, -2.645485041427817e-02, -2.635889410900177e-02, -2.621375020815588e-02, -2.599020253244392e-02, -2.563944550278057e-02, -2.508870457555508e-02, -2.432995677508993e-02, -2.486034606369708e-02, -3.069956816636933e-02, -4.852515914749754e-02, -3.790059010179481e-02, -2.438812603307548e-02, -1.919842061929629e-02, -1.375307017604555e-02, -7.202859276511400e-03, -2.430284618544741e-03, -4.023448353777482e-04, -1.922684471051198e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


